import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

// THE LAST LAMP — a small, complete first-person temple mystery.
const $ = (id) => document.getElementById(id);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101715);
scene.fog = new THREE.FogExp2(0x101715, 0.027);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 90);
camera.position.set(0, 1.65, 15.1);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.08;
document.body.prepend(renderer.domElement);
const hemi = new THREE.HemisphereLight(0x9ca99c, 0x241d16, 1.05); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xb7cbbd, 1.15); moon.position.set(-5, 14, 8); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -22; moon.shadow.camera.right = 22; moon.shadow.camera.top = 24; moon.shadow.camera.bottom = -24; scene.add(moon);
const lanternLight = new THREE.PointLight(0xffa844, 1.7, 8, 2); camera.add(lanternLight); lanternLight.position.set(.22,-.25,-.25); scene.add(camera);
const gold = new THREE.MeshStandardMaterial({ color:0x9a7137, metalness:.7, roughness:.34 });
const stone = new THREE.MeshStandardMaterial({ color:0x5c5547, roughness:.92 });
const darkStone = new THREE.MeshStandardMaterial({ color:0x34362f, roughness:.94 });
const redPaint = new THREE.MeshStandardMaterial({ color:0x8c4334, roughness:.8 });
const floorMat = new THREE.MeshStandardMaterial({ color:0x363a34, roughness:.83 });
const colliders = [], interactables = [], animatables = [];
function box(name, x,y,z, sx,sy,sz, mat, collision=true, cast=true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), mat); mesh.name=name; mesh.position.set(x,y,z); mesh.castShadow=cast; mesh.receiveShadow=true; scene.add(mesh);
  if(collision) colliders.push({x,z,hx:sx/2,hz:sz/2, bottom:y-sy/2, top:y+sy/2}); return mesh;
}
function cylinder(x,y,z, rt, rb, h, mat, sides=12, collision=false) {
  const mesh=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,sides),mat); mesh.position.set(x,y,z); mesh.castShadow=true;mesh.receiveShadow=true;scene.add(mesh); return mesh;
}
function pointLight(x,y,z,color,intensity,range){const l=new THREE.PointLight(color,intensity,range,2);l.position.set(x,y,z);scene.add(l);return l;}
// Temple floor, stone walls and a darkened, rain-stained ceiling.
box('Temple flagstones',0,-.18,0,30,.36,36,floorMat,false);
box('North wall',0,2.4,-18,30,4.8,.7,stone); box('South wall',0,2.4,18,30,4.8,.7,stone);
box('West wall',-15,2.4,0,.7,4.8,36,stone); box('East wall',15,2.4,0,.7,4.8,36,stone);
box('Ceiling',0,5,0,30,.35,36,new THREE.MeshStandardMaterial({color:0x282e29,roughness:1}),false,false);
// Long pillared galleries. Openings in the divider lead to the two small evidence rooms.
for (const x of [-7.55,7.55]) {
  for(const [a,b] of [[-18,-9],[-3,7],[12,18]]) box('gallery divider',x,2.25,(a+b)/2,.55,4.5,b-a,stone);
}
// Chamber cross-walls, each with a narrow doorway.
box('west chamber wall',-11.2,2.1,-7,7.6,4.2,.45,darkStone); // opening x -12.5..-9.9 is left open by visual door frame
// split out the doorway in the north/south direction with lintel elements only
box('east chamber wall',11.2,2.1,7,7.6,4.2,.45,darkStone);
// Stone door frames (no door, just old lintels and uprights).
for (const [x,z] of [[-7.5,-6],[7.5,9]]) {
  for(const dz of [-2.7,2.7]) box('carved doorway post',x,1.5,z+dz,.55,3,.55,stone,false);
  box('door lintel',x,3.15,z, .65,.45,6,gold,false);
}
// Decorative repeated pillars with layered capitals and plinths.
for(const x of [-5.4,5.4]) for(const z of [-14,-8,-2,4,10,15]) {
  cylinder(x,.48,z,.7,.76,.55,darkStone,8); cylinder(x,2.0,z,.42,.52,2.65,stone,8);
  cylinder(x,3.48,z,.72,.56,.45,gold,8); cylinder(x,3.78,z,.62,.62,.18,redPaint,8);
  // faint carved bands
  cylinder(x,2.75,z,.44,.44,.11,gold,8);
}
// Wall pilasters, vermilion border and hanging brass lamps.
for(const z of [-15,-10,-4,2,8,14]) for(const x of [-14.45,14.45]) {
  box('wall pilaster',x,2.1,z,.35,4.15,.42,darkStone,false);
  box('pilaster cap',x,4.25,z,.58,.24,.62,gold,false);
}
box('vermilion frieze',0,4.12,-17.57,28,.15,.08,redPaint,false);
for(const z of [-13,-5,3,11]) for(const x of [-10.2,10.2]) {
  const chain=cylinder(x,3.65,z,.025,.025,.75,gold,6); chain.position.y=3.45;
  cylinder(x,2.95,z,.34,.18,.13,gold,10); cylinder(x,3.08,z,.07,.07,.22,gold,8);
  const flame=new THREE.Mesh(new THREE.SphereGeometry(.11,8,8),new THREE.MeshBasicMaterial({color:0xffad43})); flame.position.set(x,3.22,z);scene.add(flame);
  const l=pointLight(x,3.25,z,0xff9638,.8,5); animatables.push({type:'light',obj:l,base:.8,seed:Math.random()*7});
}
// Center aisle runner tiles and an intricate sunburst floor medallion.
for(let z=-16;z<=16;z+=2) {
  const tile=new THREE.Mesh(new THREE.BoxGeometry(2.5,.025,1.8),new THREE.MeshStandardMaterial({color:z%4===0?0x4a4031:0x3c4039,roughness:.7}));tile.position.set(0,.015,z);tile.receiveShadow=true;scene.add(tile);
}
cylinder(0,.04,-1,2.05,2.05,.06,gold,32); cylinder(0,.08,-1,1.75,1.75,.04,stone,32);
for(let i=0;i<16;i++){const a=i*Math.PI/8;const petal=box('sunburst',Math.sin(a)*1.24,.11,-1+Math.cos(a)*1.24,.18,.035,.8,gold,false,false);petal.rotation.y=-a;}
// South threshold and distant, stylized gopuram relief, visible above the rear lintel.
box('threshold',0,.02,17.6,5,.16,.7,gold,false);
for(let tier=0;tier<5;tier++) {
  const w=4.5-tier*.6,h=.45; const block=box('painted gopuram tier',0,5.1+tier*.45,-17.35,w,h,.45,tier%2?redPaint:gold,false);
  for(let j=0;j<5-tier;j++){const tx=(j-(4-tier)/2)*.7; cylinder(tx,5.28+tier*.45,-17.04,.12,.17,.22,tier%2?gold:redPaint,8,false);}
}

