// Sacred spaces and story objects: handmade geometry keeps everything self-contained.
function altar(x,z) {
  box('altar base',x,.38,z,3.8,.7,2.2,darkStone); box('altar gold rim',x,.78,z,4,.12,2.35,gold,false);
  box('sanctum slab',x,1.15,z,2.7,.65,1.35,stone); box('altar crown',x,1.55,z,3.1,.16,1.6,gold,false);
  box('offering cloth',x,1.65,z,.95,.08,.92,redPaint,false);
  for(const dx of [-1.35,1.35]) {cylinder(x+dx,1.13,z,.16,.19,.7,gold,10);cylinder(x+dx,1.5,z,.22,.22,.08,gold,10);}
  // Bronze Nandi-like abstract guardian relief (not a deity depiction).
  const lamp=cylinder(x,1.88,z,.2,.29,.45,gold,10); lamp.rotation.x=Math.PI;
  const flame=new THREE.Mesh(new THREE.SphereGeometry(.14,10,8),new THREE.MeshBasicMaterial({color:0xffae4d}));flame.position.set(x,2.25,z);scene.add(flame);
  pointLight(x,2.4,z,0xffa43d,1.25,8);
}
altar(0,-14.2);
// Central hanging temple bell, its rope and stone platform.
box('bell plinth',0,.19,12.6,2.4,.36,2.1,darkStone);
const bell=cylinder(0,3.0,12.5,.55,.3,1.05,gold,12); bell.position.y=3.0;
cylinder(0,3.65,12.5,.12,.12,.5,gold,8); cylinder(0,3.86,12.5,.035,.035,.3,redPaint,6);
const bellRope=cylinder(.48,2.7,12.2,.035,.035,1.7,redPaint,6); bellRope.position.set(.5,2.65,12.2); bellRope.rotation.z=-.22;
// Palm-leaf archive table in the west room.
box('archive table',-11, .77,-12.1,3.1,.18,1.8,gold); for(const dx of [-1.25,1.25])for(const dz of [-.65,.65])box('table leg',-11+dx,.38,-12.1+dz,.13,.8,.13,darkStone);
for(let i=0;i<5;i++){const leaf=box('palm leaf manuscript',-11,.89+i*.025,-12.1,.8,.025,1.05,i%2?redPaint:gold,false,false);leaf.rotation.y=(i-2)*.025;}
// Eastern lamp-keeper's chamber: oil jars, cot and a copper anklet.
box('low cot',11,.42,11.3,3.3,.28,1.6,darkStone,false);box('cot mat',11,.62,11.3,3.05,.15,1.4,redPaint,false);
for(const [x,z] of [[9.5,10],[12.5,12],[12,9.5]]) {cylinder(x,.55,z,.38,.48,.9,stone,10);cylinder(x,1.04,z,.18,.35,.14,gold,10);}
for(let i=0;i<3;i++){const bead=new THREE.Mesh(new THREE.TorusGeometry(.23+i*.06,.035,8,24),gold);bead.rotation.x=Math.PI/2;bead.position.set(11,.8+i*.06,11.3);scene.add(bead);}
// wall niches, simple lotus-like reliefs and scattered stone bowls.
for(const [x,z] of [[-13.8,-13.7],[-13.8,4],[13.8,-13.4],[13.8,-3]]) {
  box('wall niche',x,2.25,z,.08,1.4,1.3,darkStone,false); cylinder(x+(x<0?.08:-.08),2.15,z,.22,.3,.22,gold,10);
}
for(const [x,z] of [[-3.5,6.2],[3.3,-4.5],[-10,1],[9,-1]]) {
  cylinder(x,.12,z,.48,.58,.2,stone,12);cylinder(x,.2,z,.36,.34,.08,gold,12);
}
// Enamel-painted door panels and rain streaks add signs of age without obstructing play.
for(const x of [-14.62,14.62]) for(const z of [-8,-1,6,13]) {
  const plaque=box('old painted relief',x,2.15,z,.04,1.2,.84,redPaint,false); 
  box('relief center',x+(x<0?.03:-.03),2.16,z,.05,.42,.12,gold,false);
}
// Floating evidence markers: small, warm glows lead the eye but never reveal the answer outright.
function marker(x,y,z,color=0xe7b75d){const m=new THREE.Mesh(new THREE.OctahedronGeometry(.12,0),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));m.position.set(x,y,z);scene.add(m);const l=pointLight(x,y,z,color,1.1,3.4);animatables.push({type:'marker',obj:m,seed:Math.random()*7,baseY:y},{type:'light',obj:l,seed:Math.random()*7,base:1.1});return m;}
function addEvidence(id,title,description,coords,object,markerPos){
  const [x,y,z]=coords; const m=marker(...markerPos); interactables.push({type:'evidence',id,title,description,position:new THREE.Vector3(x,y,z),mesh:object,marker:m,found:false});
}
const ledger=box('palm-leaf bundle',-11,1.22,-12.1,.68,.14,.82,redPaint,false);ledger.rotation.y=-.12;
addEvidence('deed','The copper deed',"A palm-leaf copy names Valli as keeper of the spring-boundary deed. Beside it: “The headman diverted the water. When the rain comes, warn the lower hamlet. I will ring the bell.”",[-11,1.3,-12.1],ledger,[-11,1.85,-12.1]);
const anklet=new THREE.Mesh(new THREE.TorusGeometry(.28,.055,10,28),gold);anklet.rotation.x=Math.PI/2;anklet.position.set(11,.83,11.3);anklet.castShadow=true;scene.add(anklet);
addEvidence('anklet','Valli’s anklet',"A copper anklet, bent as if torn away. On its inner edge, a child's shaky scratch: “Akka said—first the rain, then the seed she hid.” The lamp keeper had been helping the families below the hill.",[11,.83,11.3],anklet,[11,1.45,11.3]);
const bellClapper=box('bell clapper',0,2.45,12.5,.12,.4,.12,redPaint,false);
addEvidence('witness','A child’s testimony',"A charcoal note folded into the bell rope: “She rang until the water turned. When the sun came, she would show everyone the deed. They barred the doors and left her inside.” The bell was the warning; the sun was the promise.",[.5,2.4,12.2],bellClapper,[.5,3.2,12.2]);
// A readable, interactive sanctum altar. The puzzle becomes usable after all three traces are collected.
interactables.push({type:'altar',position:new THREE.Vector3(0,1.1,-12.1)});
interactables.push({type:'bell',position:new THREE.Vector3(.5,1.1,12.2)});

// Valli: a veiled, blood-marked figure made of layered cloth, shadow and a human silhouette.
const ghost=new THREE.Group();ghost.position.set(0,.1,-16.2);ghost.visible=false;scene.add(ghost);
const sariMat=new THREE.MeshStandardMaterial({color:0x382a32,roughness:.72,transparent:true,opacity:.91,side:THREE.DoubleSide});
const shawlMat=new THREE.MeshStandardMaterial({color:0x762f32,roughness:.66,transparent:true,opacity:.94,side:THREE.DoubleSide});
const hairMat=new THREE.MeshStandardMaterial({color:0x111312,roughness:.88});
const skinMat=new THREE.MeshStandardMaterial({color:0xbba18b,roughness:.72,emissive:0x291716,emissiveIntensity:.28});
const skirt=new THREE.Mesh(new THREE.ConeGeometry(.68,1.52,10,1,true),sariMat);skirt.position.y=.9;ghost.add(skirt);
const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.29,.62,5,9),sariMat);torso.position.y=1.7;ghost.add(torso);
const drape=new THREE.Mesh(new THREE.PlaneGeometry(1.05,1.82),shawlMat);drape.position.set(.13,1.72,.24);drape.rotation.z=-.42;ghost.add(drape);
const head=new THREE.Mesh(new THREE.SphereGeometry(.28,14,12),skinMat);head.position.set(0,2.38,.05);ghost.add(head);
const hair=new THREE.Mesh(new THREE.SphereGeometry(.32,12,10),hairMat);hair.scale.set(1,1.2,.92);hair.position.set(0,2.51,-.015);ghost.add(hair);
for(let i=0;i<5;i++){const lock=new THREE.Mesh(new THREE.CylinderGeometry(.025,.055,.95+i*.12,6),hairMat);lock.position.set((i-2)*.11,1.92,-.02);lock.rotation.z=(i-2)*.09;ghost.add(lock);}
// face details lie on the front plane of the head
for(const x of [-.105,.105]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,8,7),new THREE.MeshBasicMaterial({color:0xffd4ac}));eye.position.set(x,2.4,.292);ghost.add(eye);}
const bloodMat=new THREE.MeshBasicMaterial({color:0x7d1719,transparent:true,opacity:.94,side:THREE.DoubleSide});
for(const [x,y,len,rot] of [[-.17,2.31,.45,-.08],[-.04,2.28,.6,.04],[.14,2.32,.36,.15],[.21,2.23,.3,.04]]) {const streak=new THREE.Mesh(new THREE.PlaneGeometry(.035,len),bloodMat);streak.position.set(x,y,.294);streak.rotation.z=rot;ghost.add(streak);}
for(const side of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.1,.66,4,7),sariMat);arm.position.set(side*.41,1.65,.03);arm.rotation.z=side*-.24;ghost.add(arm);}
const aura=new THREE.PointLight(0xb94438,1.05,5);aura.position.set(0,1.7,.1);ghost.add(aura);
const ghostData={active:false,stun:0,origin:new THREE.Vector3(0,.1,-16.2),speed:.68};
// Soft cinematic ambience via Web Audio, started only from a user gesture.
let audio=null;function startAudio(){if(audio)return;try{const C=window.AudioContext||window.webkitAudioContext;audio=new C();const master=audio.createGain();master.gain.value=.045;master.connect(audio.destination);for(const [freq,vol] of [[55,.48],[82.4,.22]]){const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=vol;o.connect(g).connect(master);o.start();}}catch(e){}}
function chime(){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(460,audio.currentTime);o.frequency.exponentialRampToValueAtTime(170,audio.currentTime+1.4);g.gain.setValueAtTime(.14,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.5);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+1.55);}
// State and evidence journal.
const found=new Set(), entries=[], keys={}, player={x:0,z:15.1,yaw:0,pitch:0}, moveInput={x:0,z:0}, mobileLook={x:0,y:0};
let started=false, gameWon=false, activePuzzle=false, sequence=[], toastTimer=0, locked=false, lastTime=performance.now(), lastFoot=0;
function tell(text,duration=3200){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),duration);}
function updateObjective(){const n=found.size;$('clueCount').textContent=`${n} / 3`;$('progress').style.width=`${n/3*100}%`;
  if(n<3)$('objectiveText').textContent=['Find the three traces Valli left','Search the old archive','Look in the lamp-keeper’s room','Listen at the temple bell'][n];
  else $('objectiveText').textContent='Order the signs at the sanctum';
}
function renderJournal(){const list=$('journalList');list.innerHTML='';const texts=[['The copper deed','A record of the stolen spring and the warning Valli tried to deliver.'],['Valli’s anklet','A child’s memory gives the first two signs: rain, then the seed.'],['A child’s testimony','The bell warned the village; the sun came after the storm.']];for(let i=0;i<3;i++){const e=document.createElement('div');e.className='entry'+(i>=found.size?' locked':'');e.innerHTML=`<small>${i<found.size?entries[i].title:'Trace not yet found'}</small><p>${i<found.size?entries[i].description:texts[i][1]}</p>`;list.appendChild(e);}}
function showJournal(){if($('intro').classList.contains('hidden')&&$('ending').classList.contains('hidden')&&!activePuzzle){renderJournal();$('journal').classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock();}}
function hideJournal(){$('journal').classList.add('hidden');if(started&&!gameWon&&matchMedia('(pointer:fine)').matches)renderer.domElement.requestPointerLock?.();}
function doInteract(){if(!started||gameWon||activePuzzle||!$('journal').classList.contains('hidden'))return;
 let best=null,dist=2.65; const px=camera.position.x,pz=camera.position.z;
 for(const it of interactables){if(it.found)continue;const d=Math.hypot(it.position.x-px,it.position.z-pz);if(d<dist){dist=d;best=it;}}
 if(!best){tell('The stones offer no answer from here.',1800);return;}
 if(best.type==='evidence'){
   best.found=true;found.add(best.id);entries.push(best);best.marker.visible=false;
   if(best.mesh)best.mesh.material=best.mesh.material.clone();
   tell(`Evidence recorded · ${best.title}`,2600);updateObjective();renderJournal();
   if(found.size===1){ghost.visible=true;ghostData.active=true;tell('A bell rings somewhere in the dark. Something has noticed you.',3800);}
   if(found.size===3){tell('The three signs are clear. Find the altar in the north sanctum.',4000);chime();}
 }else if(best.type==='altar'){
   if(found.size<3){tell('The sanctum is sealed. Three traces are missing.',2300);return;}
   activePuzzle=true;sequence=[];$('sequence').innerHTML='Choose three signs';$('puzzleMessage').textContent='';$('puzzle').classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock();
 }else if(best.type==='bell'){chime();bell.rotation.z=.1;setTimeout(()=>bell.rotation.z=0,450);tell('The bell answers. The echo rolls down the hill.',2200);}
}
function completePuzzle(){if(sequence.length!==3){$('puzzleMessage').textContent='Offer exactly three signs.';return;}
 const answer=['rain','seed','sun'];if(sequence.join(',')!==answer.join(',')){$('puzzleMessage').textContent='The lamp gutters. The story is still out of order.';sequence=[];$('sequence').innerHTML='Choose three signs';return;}
 activePuzzle=false;gameWon=true;$('puzzle').classList.add('hidden');$('ending').classList.remove('hidden');ghostData.active=false;ghost.visible=false;chime();}
function bindPuzzle(){document.querySelectorAll('.sym').forEach(b=>b.addEventListener('click',()=>{if(sequence.length<3){sequence.push(b.dataset.sym);$('sequence').innerHTML=sequence.map(s=>`<span>${{rain:'☔ Rain',seed:'❋ Seed',sun:'☼ Sun'}[s]}</span>`).join(' → ');}}));$('resetPuzzle').onclick=()=>{sequence=[];$('sequence').textContent='Choose three signs';$('puzzleMessage').textContent='';};$('offerBtn').onclick=completePuzzle;}
bindPuzzle();updateObjective();

// First-person controls, with a pointer-lock mouse on desktop and a touch stick/look zone on phones.
function setView(){camera.rotation.order='YXZ';camera.rotation.y=player.yaw;camera.rotation.x=player.pitch;}
function startGame(){if(started)return;started=true;startAudio();$('intro').classList.add('hidden');if(matchMedia('(pointer:fine)').matches)renderer.domElement.requestPointerLock?.();tell('Find the archive, the lamp-keeper’s room, and the bell.',3800);}
$('startBtn').addEventListener('click',startGame);
